#include <tuple>
#include <algorithm>

class Solution {
public:
    int subtreeInversionSum(std::vector<std::vector<int>>& edges, std::vector<int>& nums, int k) {
        int n = edges.size() + 1;
        std::vector<std::vector<int>> graph(n);
        for (const auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
        }

        std::vector<int> parent(n, -1);
        std::map<std::tuple<int, int, bool>, int> memo;

        auto dfs = [&](auto& self, int u, int steps, bool inverted) -> int {
            auto key = std::make_tuple(u, steps, inverted);
            if (memo.count(key)) return memo[key];

            int val = inverted ? -nums[u] : nums[u];
            int neg_val = -val;

            for (int v : graph[u]) {
                if (v != parent[u]) {
                    parent[v] = u;
                    val += self(self, v, std::min(k, steps + 1), inverted);
                    if (steps == k) {
                        neg_val += self(self, v, 1, !inverted);
                    }
                }
            }
            int res = (steps == k) ? std::max(val, neg_val) : val;
            return memo[key] = res;
        };

        return dfs(dfs, 0, k, false);
    }
};

import java.util.*;

class Solution {
    private List<Integer>[] graph;
    private int[] parent;
    private Map<String, Integer> memo;

    public int subtreeInversionSum(int[][] edges, int[] nums, int k) {
        int n = edges.length + 1;
        graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        parent = new int[n];
        Arrays.fill(parent, -1);
        memo = new HashMap<>();

        return dfs(0, k, false, nums, k);
    }

    private int dfs(int u, int steps, boolean inverted, int[] nums, int k) {
        String key = u + "," + steps + "," + inverted;
        if (memo.containsKey(key)) return memo.get(key);

        int val = inverted ? -nums[u] : nums[u];
        int negVal = -val;

        for (int v : graph[u]) {
            if (v != parent[u]) {
                parent[v] = u;
                val += dfs(v, Math.min(k, steps + 1), inverted, nums, k);
                if (steps == k) {
                    negVal += dfs(v, 1, !inverted, nums, k);
                }
            }
        }
        int res = (steps == k) ? Math.max(val, negVal) : val;
        memo.put(key, res);
        return res;
    }
}

