var subtreeInversionSum = function(edges, nums, k) {
    const n = edges.length + 1;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const parent = new Array(n).fill(-1);
    const memo = new Map();

    function dfs(u, steps, inverted) {
        const key = `${u},${steps},${inverted}`;
        if (memo.has(key)) return memo.get(key);

        let val = inverted ? -nums[u] : nums[u];
        let negVal = -val;

        for (const v of graph[u]) {
            if (v !== parent[u]) {
                parent[v] = u;
                val += dfs(v, Math.min(k, steps + 1), inverted);
                if (steps === k) {
                    negVal += dfs(v, 1, !inverted);
                }
            }
        }
        const res = steps === k ? Math.max(val, negVal) : val;
        memo.set(key, res);
        return res;
    }

    return dfs(0, k, false);
};
